<style lang="scss" src="./table-header-filter.scss" scoped></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import { MountingPortal } from "portal-vue";
import {
  destroyModalRootContent,
  ensureModalRoot
} from "../../util/ensure-modal-root";
import Icon from "../../components/icon/icon";
import SearchField from "../../components/search-field/search-field";
import { SearchFieldMode } from "../../components/search-field/search-field.constants";
import { IconShape } from "../icon/icon.constants";
import { hasChild } from "../../util/has-child";

@Component({
  components: {
    MountingPortal,
    Icon,
    SearchField
  }
})
export default class TableHeaderFilter extends Vue {
  @Prop({
    type: Object,
    default: () =>
      Object.assign({}, { left: 0, top: 0, width: 200, height: 100 })
  })
  bounds;

  @Prop({
    type: Number,
    default: 200
  })
  manualWidth;

  @Prop({
    type: Object,
    default: () => ({
      sort: 80,
      paddings: 37,
      header: 34,
      search: 32
    })
  })
  heightMetrics;

  @Prop({
    type: Array,
    default: () => []
  })
  filterOptions;

  @Prop({
    type: Array,
    default: () => []
  })
  sortOptions;

  @Prop({
    type: String,
    default: ""
  })
  searchDefaultValue;

  /** Modal root this dropdown renders into */
  modalRoot = null;
  SearchFieldMode = SearchFieldMode;
  filterOptionSelected = [];

  beforeMount() {
    destroyModalRootContent("TableHeaderFilter");
    this.modalRoot = ensureModalRoot();

    if (!this.modalRoot) return;

    for (let i = 0; i < this.filterOptions.length; i++) {
      this.filterOptionSelected[i] = this.filterOptions[i].selected;
    }
  }

  willUpdate() {
    this.modalRoot = ensureModalRoot();

    if (!this.modalRoot) {
      console.warn("Could not establish modal root for floating componentry");
      return;
    }
  }

  calculateHeight() {
    const { heightMetrics, filterOptions, sortOptions } = this;
    const { paddings, header, search } = heightMetrics;
    const filterOptionHeight = filterOptions.length * 40;
    const sortOptionHeight = sortOptions.length * 40;
    if (filterOptionHeight > 0 ) {
      return paddings + header + search + filterOptionHeight + sortOptionHeight;
    } else {
      return header + sortOptionHeight - 15;
    }
  }

  get IconShape() {
    return IconShape;
  }

  handleDocumentDown(e) {
    // This helps some cases where the menu is long gone but the event persists.
    // This is mostly with bugs in storybook that needs this hand holding.
    if (!hasChild(document, this.$refs.container)) {
      this.clearListeners();
    }

    // Test to see if the target is a child of this menu. If not, this menu is
    // closed. If yes, we let the event proceed naturally.
    if (hasChild(this.$refs.container, e.target)) return;
    e.stopPropagation();
    e.stopImmediatePropagation();
    e.preventDefault();

    /**
     * Emits a close event when the menu detects an interaction that warrants
     * dismissing the menu
     *
     * @event close
     */
    this.$emit("close", e.target);
  }

  mounted() {
    document.addEventListener("mousedown", this.handleDocumentDown);
    document.addEventListener("touchstart", this.handleDocumentDown);
    document.addEventListener("wheel", this.handleDocumentDown, {
      passive: false
    });
  }

  beforeDestroy() {
    this.clearListeners();
  }

  clearListeners() {
    document.removeEventListener("mousedown", this.handleDocumentDown);
    document.removeEventListener("touchstart", this.handleDocumentDown);
    document.removeEventListener("wheel", this.handleDocumentDown);
  }

  get modalRootId() {
    return `#${this.modalRoot.id}`;
  }

  get style() {
    let { bounds = { left: 0, top: 0, width: 207, height: 100 }, width } = this;

    const height = this.calculateHeight();
    width = 207;
    bounds.right = bounds.left + bounds.width;

    const viewBox = {
      top: `${bounds.bottom - 3}px`,
      left: `${bounds.right - width}px`,
      width: `${width || 100}px`,
      height: `${height}px`
    };

    return viewBox;
  }

  getSelected(index) {
    return this.filterOptionSelected[index];
  }

  handleSortIncrease() {
    /**
     * onSortIncrease when user selects sort increase
     *
     * @event onSortIncrease
     */
    this.$emit("onSortIncrease");
  }

  handleSortDecrease() {
    /**
     * onSortDecrease when user selects sort decrease
     *
     * @event
     */
    this.$emit("onSortDecrease");
  }

  handleInput(value) {
    /**
     * input event when user input something into the search field
     *
     * @event input
     */
    this.$emit("input", value);
  }

  handleSelectOption(index) {
    this.filterOptionSelected[index] = !this.filterOptionSelected[index];
    this.$forceUpdate();
    /**
     * selectOption event when a filter option is selected
     *
     * @event selectOption
     */
    this.$emit("selectOption", index);
  }

  handleSort(index) {
    /**
     * Sort event when a sort option is selected
     *
     * @event sort
     */
    this.$emit("sort", index);
  }

  handleSelectAll() {
    for (let i = 0; i < this.filterOptionSelected.length; i++) {
      this.filterOptionSelected[i] = true;
    }
    this.$forceUpdate();
    /**
     * selectAll event when selectAll is clicked by the user.
     *
     * @event selectAll
     */
    this.$emit("selectAll");
  }

  handleClear() {
    for (let i = 0; i < this.filterOptionSelected.length; i++) {
      this.filterOptionSelected[i] = false;
    }
    this.$forceUpdate();
    /**
     * Clear event when the clear is clicked by the user.
     *
     * @event clear
     */
    this.$emit("clear");
  }
}
</script>

<template>
  <MountingPortal :mountTo="modalRootId" append>
    <div class="TableHeaderFilter" :style="style" ref="container">
      <div class="TableHeaderFilter__Upper">
        <div
          v-for="(option, index) of sortOptions"
          :key="index"
          class="TableHeaderFilter__Sort"
          @click="handleSort(index)"
        >
          {{ option.label }}
        </div>
      </div>
      <div v-if="filterOptions && filterOptions.length" class="TableHeaderFilter__Lower">
        <div class="TableHeaderFilter__Control">
          <div class="TableHeaderFilter__FilterBy">Filter by</div>
          <div class="TableHeaderFilter__Select">
            <span class="TableHeaderFilter__SelectAll" @click="handleSelectAll"
              >Select All</span
            >
            /
            <span class="TableHeaderFilter__Clear" @click="handleClear"
              >Clear</span
            >
          </div>
        </div>
        <SearchField
          class="TableHeaderFilter__Search"
          :mode="SearchFieldMode.GMS"
          :defaultValue="searchDefaultValue"
          @input="handleInput"
        />
        <div class="TableHeaderFilter__Options">
          <div
            v-for="(item, index) in filterOptions"
            :key="index"
            class="TableHeaderFilter__Option"
            @click="handleSelectOption(index)"
          >
            <div class="TableHeaderFilter__Check">
              <Icon
                v-if="getSelected(index)"
                :shape="IconShape.CHECK"
                :size="12"
                color="#2356F6"
              />
            </div>
            <div class="TableHeaderFilter__OptionContent">{{ item.label }}</div>
          </div>
        </div>
      </div>
    </div>
  </MountingPortal>
</template>
